// @pit: {"label": "Verify collapsed entries in outline and recover one original via inspectEntry"}
async ({ session: { outline, inspectEntry } }) => {
  const o: any = await outline({ previewChars: 600 });
  const entries = o.entries ?? [];
  const byState: Record<string, number> = {};
  for (const e of entries) byState[e.state] = (byState[e.state] ?? 0) + 1;
  const collapsed = entries.filter((e: any) => String(e.preview).startsWith("[Pit: collapsed"));
  const first = collapsed[0];
  const ids = first ? [...String(first.preview).matchAll(/inspectEntry\("(\d+)"\)/g)].map((m) => m[1]) : [];
  const originals = await Promise.all(ids.map(async (id) => {
    const r: any = await inspectEntry(id, { limit: 6 });
    return { id, role: r.original?.role ?? r.role, text: String(r.original?.text ?? "").slice(0, 240) };
  }));
  return {
    estimatedTokens: o.estimatedTokens, count: entries.length, byState,
    collapsedCount: collapsed.length,
    collapsedTokens: collapsed.reduce((s: number, e: any) => s + e.tokens, 0),
    sample: collapsed.slice(0, 3).map((e: any) => `${e.id} ${e.state} ${e.tokens}: ${e.preview}`),
    originals,
  };
}
